  ctx={'profile':'readout-line-2560x1440','imageSize':[892,48],'frameSize':original['input']['frameSize'],'roi':original['input']['rect']}
  c=audit(original['detections']['candidate']['contrast'],decode(original['detections']['candidate']['contrast']),cal,ctx)
